-- SQL Schema generated by MODT

CREATE TABLE Depot (
    id INT PRIMARY KEY AUTO_INCREMENT,
    code VARCHAR(20) UNIQUE NOT NULL,
    city VARCHAR(80) NOT NULL,
    timezone VARCHAR(40)
);

CREATE TABLE Driver (
    id INT PRIMARY KEY AUTO_INCREMENT,
    driverCode VARCHAR(30) UNIQUE NOT NULL,
    fullName VARCHAR(140) NOT NULL,
    licenseClass VARCHAR(20),
    status VARCHAR(20)
);

CREATE TABLE Vehicle (
    id INT PRIMARY KEY AUTO_INCREMENT,
    vin VARCHAR(32) UNIQUE NOT NULL,
    plateNumber VARCHAR(20) UNIQUE NOT NULL,
    operationalState VARCHAR(255),
    currentOdometer BIGINT,
    gpsEnabled BOOLEAN DEFAULT TRUE,
    hosts INT,
    FOREIGN KEY (hosts) REFERENCES Depot(id)
);

CREATE TABLE ElectricVehicle (
    id INT PRIMARY KEY AUTO_INCREMENT,
    parent INT,
    batteryCapacityKWh DECIMAL(8,2),
    connectorType VARCHAR(30),
    FOREIGN KEY (parent) REFERENCES Vehicle(id)
);

CREATE TABLE Trip (
    id INT PRIMARY KEY AUTO_INCREMENT,
    routeCode VARCHAR(30) NOT NULL,
    dispatchState VARCHAR(255),
    scheduledDeparture TIMESTAMP NULL,
    actualArrival TIMESTAMP NULL,
    dispatches INT,
    executes INT,
    FOREIGN KEY (dispatches) REFERENCES Depot(id),
    FOREIGN KEY (executes) REFERENCES Vehicle(id)
);

CREATE TABLE SensorAlert (
    id INT PRIMARY KEY AUTO_INCREMENT,
    source VARCHAR(60) NOT NULL,
    severity VARCHAR(20),
    alertState VARCHAR(255),
    createdAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    emits INT,
    FOREIGN KEY (emits) REFERENCES Vehicle(id)
);

CREATE TABLE WorkOrder (
    id INT PRIMARY KEY AUTO_INCREMENT,
    workOrderNumber VARCHAR(30) UNIQUE NOT NULL,
    maintenanceState VARCHAR(255),
    severity VARCHAR(20),
    openedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    requires INT,
    reports INT,
    FOREIGN KEY (requires) REFERENCES Vehicle(id),
    FOREIGN KEY (reports) REFERENCES Driver(id)
);

CREATE TABLE InspectionChecklist (
    id INT PRIMARY KEY AUTO_INCREMENT,
    checklistName VARCHAR(120) NOT NULL,
    revision VARCHAR(20),
    uses INT,
    FOREIGN KEY (uses) REFERENCES WorkOrder(id)
);

CREATE TABLE Driver_certified_for_Vehicle (
    Driver_id INT,
    Vehicle_id INT,
    PRIMARY KEY (Driver_id, Vehicle_id),
    FOREIGN KEY (Driver_id) REFERENCES Driver(id),
    FOREIGN KEY (Vehicle_id) REFERENCES Vehicle(id)
);

